export function ViewTransition({
  view = {{view}},
  style = "{{style}}",
  duration = {{duration}},
  accent = "{{accent}}",
}) {
  const anim = { morph: "mot-vt-morph", fade: "mot-vt-fade", slide: "mot-vt-slide" }[style];
  return (
    <div style={{ position: "relative", width: "100%", maxWidth: 320, height: 90, background: "#FAF7F2", border: "1px solid #24143022", borderRadius: 12, overflow: "hidden", fontFamily: "system-ui, sans-serif", fontSize: 12, color: "#241430aa" }}>
      <div className={!view ? "view active" : "view"} style={{ position: "absolute", inset: 0, display: "grid", placeItems: "center", fontWeight: 700, fontSize: 14, color: "#241430", background: accent, opacity: view ? 0 : undefined }}>List view</div>
      <div className={view ? "view active" : "view"} style={{ position: "absolute", inset: 0, display: "grid", placeItems: "center", fontWeight: 700, fontSize: 14, color: "#241430", background: "#fff", border: "2px dashed #24143033", opacity: view ? undefined : 0 }}>Detail view</div>
      <p style={{ position: "absolute", bottom: -24, left: 0 }}>{style} &middot; {duration}ms &middot; approximates the native View Transitions API with a CSS crossfade</p>
      <style>{`
        @media (prefers-reduced-motion: no-preference) {
          .view.active { animation: ${anim} ${duration}ms ease-out; }
          @keyframes mot-vt-morph { from { opacity: 0; transform: scale(.9) rotate(-2deg); } to { opacity: 1; transform: scale(1) rotate(0); } }
          @keyframes mot-vt-fade { from { opacity: 0; } to { opacity: 1; } }
          @keyframes mot-vt-slide { from { opacity: 0; transform: translateX(24px); } to { opacity: 1; transform: translateX(0); } }
        }
      `}</style>
    </div>
  );
}
